type Obj = Record<string, unknown>;
const obj = (value: unknown): Obj => value !== null && typeof value === "object" && !Array.isArray(value) ? value as Obj : {};
const array = (value: unknown): unknown[] => Array.isArray(value) ? value : [];
const id = (value: unknown): string | null => typeof value === "string" && /^\d+$/.test(value) ? value : null;
function integer(value: unknown): number | null {
  if (typeof value === "number" && Number.isInteger(value) && value >= 0) return value;
  if (typeof value !== "string" || !/^\d+$/.test(value.trim())) return null;
  const parsed = Number(value); return Number.isSafeInteger(parsed) ? parsed : null;
}

export const NFL_EVENT_FUMBLES_NORMALIZATION_VERSION = "espn_nfl_event_summary_fumbles_v1";

export function espnNflEventSummaryUrl(eventId: string) {
  if (!/^\d+$/.test(eventId)) throw new Error("Invalid NFL event ID");
  return `https://site.web.api.espn.com/apis/site/v2/sports/football/nfl/summary?event=${eventId}`;
}

/** Production acquisition wrapper; strict FUM/LOST validation remains below. */
export async function fetchEspnNflEventFumbles(eventId: string, fetcher: typeof fetch = fetch) {
  const source = espnNflEventSummaryUrl(eventId);
  const response = await fetcher(source, { signal: AbortSignal.timeout(30_000) });
  if (!response.ok) throw new Error(`ESPN NFL event summary HTTP ${response.status}: ${eventId}`);
  return normalizeEspnNflEventFumbles(await response.json(), { eventId, fetchedAt: new Date().toISOString() });
}

/** Strictly normalize only the factual FUM/LOST evidence used by offline NFL research. */
export function normalizeEspnNflEventFumbles(payload: unknown, request: { eventId: string; fetchedAt: string }) {
  const source = espnNflEventSummaryUrl(request.eventId);
  if (!Number.isFinite(Date.parse(request.fetchedAt))) throw new Error("Invalid fumble-summary provenance timestamp");
  const p = obj(payload), header = obj(p.header), competition = array(header.competitions)[0];
  if (String(header.id ?? "") !== request.eventId || String(obj(competition).id ?? "") !== request.eventId) throw new Error("ESPN summary event identity mismatch");
  const teams = array(obj(p.boxscore).players);
  if (!teams.length) throw new Error("ESPN summary missing boxscore players");
  const rows = new Map<string, { providerPlayerId: string; totalFumbles: number; fumblesLost: number; recoveries: number | null }>();
  let groups = 0;
  for (const rawTeam of teams) {
    const statistics = obj(rawTeam).statistics;
    if (!Array.isArray(statistics)) throw new Error("ESPN summary team missing statistics");
    for (const rawGroup of statistics) {
      const group = obj(rawGroup);
      if (group.name !== "fumbles") continue;
      groups++;
      if (!Array.isArray(group.labels) || !(group.labels as unknown[]).every(label => typeof label === "string") || !Array.isArray(group.athletes)) throw new Error("ESPN fumbles group malformed");
      const labels = group.labels as string[], lostIndex = labels.indexOf("LOST"), totalIndex = labels.indexOf("FUM"), recoveriesIndex = labels.indexOf("REC");
      if (lostIndex < 0 || totalIndex < 0) throw new Error("ESPN fumbles group missing FUM or LOST label");
      for (const rawAthlete of group.athletes) {
        const athleteRow = obj(rawAthlete), athleteId = id(obj(athleteRow.athlete).id), stats = array(athleteRow.stats);
        if (!athleteId) throw new Error("ESPN fumbles row missing athlete ID");
        if (stats.length !== labels.length) throw new Error(`ESPN fumbles stat-array length mismatch: ${athleteId}`);
        const totalFumbles = integer(stats[totalIndex]), fumblesLost = integer(stats[lostIndex]), recoveries = recoveriesIndex < 0 ? null : integer(stats[recoveriesIndex]);
        if (totalFumbles === null || fumblesLost === null || (recoveriesIndex >= 0 && recoveries === null)) throw new Error(`ESPN fumbles values invalid: ${athleteId}`);
        if (rows.has(athleteId)) throw new Error(`Duplicate ESPN fumbles athlete row: ${athleteId}`);
        rows.set(athleteId, { providerPlayerId: athleteId, totalFumbles, fumblesLost, recoveries });
      }
    }
  }
  if (!groups) throw new Error("ESPN summary missing fumbles statistics group");
  return { eventId: request.eventId, source, fetchedAt: new Date(request.fetchedAt).toISOString(), normalizationVersion: NFL_EVENT_FUMBLES_NORMALIZATION_VERSION,
    athletes: [...rows.values()].sort((left, right) => Number(left.providerPlayerId) - Number(right.providerPlayerId)) };
}

import { NFL_OBSERVATION_NORMALIZATION_VERSION, type NflObservation } from "./observationFoundation";
import { buildNflObservation, type NflEligiblePlayer, type NflFinalEvent, type NflFumbleEvidence } from "./observationIngestion";
import type { NflGameLogObservation } from "../providers/espnNflGameLog";

type FumbleSummary = { eventId: string; source: string; fetchedAt: string; athletes: Array<{ providerPlayerId: string; fumblesLost: number }> };

export type NflObservationAcquisition = {
  eligible: readonly NflEligiblePlayer[];
  season: number;
  finalEvents: readonly NflFinalEvent[];
  gameLogs: readonly NflGameLogObservation[];
  fetchFumbles: (eventId: string) => Promise<FumbleSummary>;
};

/**
 * Builds complete factual rows only after final-state and QB LOST evidence are
 * both available. A summary is fetched once per final QB event, never per QB.
 */
export async function acquireNflObservations(input: NflObservationAcquisition) {
  const finalIds = new Set(input.finalEvents.filter(event => event.season === input.season && event.completed).map(event => event.providerEventId));
  const eligibleById = new Map(input.eligible.map(player => [player.providerPlayerId, player]));
  const logs = input.gameLogs.filter(row => row.season === input.season && eligibleById.has(row.providerPlayerId) && finalIds.has(row.eventId));
  const qbEventIds = [...new Set(logs.filter(row => row.position === "QB").map(row => row.eventId))].sort((a, b) => Number(a) - Number(b));
  const fumbles: NflFumbleEvidence[] = [];
  for (const eventId of qbEventIds) {
    const summary = await input.fetchFumbles(eventId);
    if (summary.eventId !== eventId) throw new Error(`NFL fumble summary identity mismatch: ${eventId}`);
    for (const athlete of summary.athletes) fumbles.push({ providerEventId: eventId, providerPlayerId: athlete.providerPlayerId, sourceUrl: summary.source, fetchedAt: summary.fetchedAt, fumblesLost: athlete.fumblesLost });
    // A QB absent from this validated summary becomes a factual zero only here.
    for (const qb of logs.filter(row => row.position === "QB" && row.eventId === eventId)) {
      if (!summary.athletes.some(athlete => athlete.providerPlayerId === qb.providerPlayerId)) fumbles.push({ providerEventId: eventId, providerPlayerId: qb.providerPlayerId, sourceUrl: summary.source, fetchedAt: summary.fetchedAt, fumblesLost: 0 });
    }
  }
  // All game-log and (where required) summary requests have completed before
  // this factual version becomes known to this system.
  const knownAt = new Date().toISOString();
  const observations: NflObservation[] = [];
  for (const gameLog of logs) {
    const observation = buildNflObservation({ gameLog, eligible: input.eligible, finalEvents: input.finalEvents, fumbles, knownAt, normalizationVersion: NFL_OBSERVATION_NORMALIZATION_VERSION });
    if (observation) observations.push(observation);
  }
  return observations.sort((left, right) => left.gameAt.localeCompare(right.gameAt) || Number(left.providerPlayerId) - Number(right.providerPlayerId) || Number(left.providerEventId) - Number(right.providerEventId));
}

import { timingSafeEqual } from 'node:crypto';
import { NextResponse } from 'next/server';
import { refreshNbaProjectionBatch } from '@/lib/analytics/nba/projectionRefresh.server';
import { loadActiveResolvedNbaProviderPlayerIds, loadActiveResolvedNbaPlayerIds, loadNbaProviderIdentities, nbaProjectionGenerationRepository, upsertNbaProjectionObservations } from '@/lib/analytics/nba/projectionRepository.server';
import { persistNbaProjectionObservations } from '@/lib/analytics/nba/projectionIngestion.server';
import { generateNbaProjectionStatCache } from '@/lib/analytics/nba/projectionGeneration.server';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 300;

function authorized(request: Request) {
  const expected = process.env.NBA_PROJECTION_INGEST_SECRET?.trim();
  const received = request.headers.get('authorization');
  if (!expected || !received?.startsWith('Bearer ')) return false;
  const actual = received.slice('Bearer '.length), expectedBytes = Buffer.from(expected), actualBytes = Buffer.from(actual);
  return expectedBytes.length === actualBytes.length && timingSafeEqual(expectedBytes, actualBytes);
}

/** Machine-to-machine only; future scheduler calls this in provider-athlete batches of 50 or fewer. */
export async function POST(request: Request) {
  if (!authorized(request)) return NextResponse.json({ error: 'Unauthorized.' }, { status: 401, headers: { 'Cache-Control': 'no-store' } });
  try {
    const body = await request.json() as Record<string, unknown>;
    if (body.action === 'eligible') {
      return NextResponse.json({ providerPlayerIds: await loadActiveResolvedNbaProviderPlayerIds() }, { headers: { 'Cache-Control': 'no-store' } });
    }
    if (body.action === 'observations') {
      const season = Number(body.season), observations = body.observations;
      if (!Number.isInteger(season) || !Array.isArray(observations) || observations.length > 5_000) {
        return NextResponse.json({ error: 'Valid season and bounded normalized observations are required.' }, { status: 400 });
      }
      const identities = await loadNbaProviderIdentities();
      const persisted = await persistNbaProjectionObservations({ observations: observations as never,
        repository: { loadProviderIdentities: async () => identities, upsertObservations: upsertNbaProjectionObservations } });
      if (body.generate === false) {
        return NextResponse.json({ ...persisted, generated: 0, unavailable: [], deferredGeneration: true }, { headers: { 'Cache-Control': 'no-store' } });
      }
      const now = new Date().toISOString(), playerIds = await loadActiveResolvedNbaPlayerIds();
      const projections = await generateNbaProjectionStatCache({ repository: nbaProjectionGenerationRepository(), playerIds, targetSeason: season, asOf: now, generatedAt: now });
      return NextResponse.json({ ...persisted, generated: projections.generated.length, unavailable: projections.unavailable, modelVersion: projections.modelVersion }, { headers: { 'Cache-Control': 'no-store' } });
    }
    if (body.action === 'generate') {
      const season = Number(body.season);
      if (!Number.isInteger(season) || season < 2000 || season > 2100) {
        return NextResponse.json({ error: 'Valid NBA season required.' }, { status: 400 });
      }
      const now = new Date().toISOString(), playerIds = await loadActiveResolvedNbaPlayerIds();
      const projections = await generateNbaProjectionStatCache({ repository: nbaProjectionGenerationRepository(), playerIds, targetSeason: season, asOf: now, generatedAt: now });
      return NextResponse.json({ generated: projections.generated.length, unavailable: projections.unavailable, modelVersion: projections.modelVersion }, { headers: { 'Cache-Control': 'no-store' } });
    }
    const season = Number(body.season), providerPlayerIds = body.providerPlayerIds;
    if (!Number.isInteger(season) || season < 2000 || season > 2100 || !Array.isArray(providerPlayerIds) || providerPlayerIds.length === 0 || providerPlayerIds.length > 50 || providerPlayerIds.some(value => !/^\d+$/.test(String(value)))) {
      return NextResponse.json({ error: 'Valid season and 1–50 ESPN athlete IDs are required.' }, { status: 400, headers: { 'Cache-Control': 'no-store' } });
    }
    const now = new Date().toISOString();
    const result = await refreshNbaProjectionBatch({ season, providerPlayerIds: providerPlayerIds?.map(String), asOf: now, generatedAt: now });
    return NextResponse.json(result, { headers: { 'Cache-Control': 'no-store' } });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'NBA projection ingestion failed.';
    return NextResponse.json({ error: message.slice(0, 400) }, { status: 500, headers: { 'Cache-Control': 'no-store' } });
  }
}
